document.addEventListener('DOMContentLoaded',()=>{const questions=document.querySelectorAll('.faq-question');questions.forEach(q=>{q.addEventListener('click',()=>{q.parentElement.classList.toggle('active')})});document.querySelectorAll('a[href^="#"]').forEach(a=>{a.addEventListener('click',e=>{const id=a.getAttribute('href').slice(1);const el=document.getElementById(id);if(el){e.preventDefault();const y=el.getBoundingClientRect().top+window.pageYOffset-80;window.scrollTo({top:y,behavior:'smooth'})}})});const revealTargets=document.querySelectorAll('.offer-card, .booking-card, .booking-side, .contact-card, .map-card, .aboutme-page, .testimonial__item');const io=new IntersectionObserver((entries)=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}})},{threshold:0.12});revealTargets.forEach(el=>io.observe(el))});
if(window.$&&window.$.fn&&typeof window.$.fn.owlCarousel==='function'){$("#certificates .gallery").owlCarousel({loop:true,margin:18,nav:false,dots:false,autoplay:false,smartSpeed:500,responsive:{0:{items:2},600:{items:3},1000:{items:5}}})}
const testimonialSlider=document.querySelector('.testimonial__slider');const testimonialItems=Array.from(document.querySelectorAll('.testimonial__item'));
if(testimonialSlider&&testimonialItems.length){let currentIndex=0;const goToItem=(index)=>{const safeIndex=Math.max(0,Math.min(index,testimonialItems.length-1));currentIndex=safeIndex;const targetItem=testimonialItems[safeIndex];targetItem.scrollIntoView({behavior:'smooth',block:'nearest',inline:'start'})};document.querySelectorAll('.testimonials .testimonial-nav-btn:not(.certificate-nav-btn)').forEach(btn=>{btn.addEventListener('click',()=>{const direction=btn.dataset.direction==='next'?1:-1;goToItem(currentIndex+direction)})})}
const certificateSlider=document.querySelector('#certificates .gallery');const certificateItems=Array.from(document.querySelectorAll('#certificates .gallery-item'));const certificateModal=document.getElementById('certificate-modal');const certificateModalImage=certificateModal?.querySelector('.certificate-modal__image');
if(certificateSlider&&certificateItems.length){let certificateIndex=0;const goToCertificateItem=(index)=>{const safeIndex=Math.max(0,Math.min(index,certificateItems.length-1));certificateIndex=safeIndex;const targetItem=certificateItems[safeIndex];targetItem.scrollIntoView({behavior:'smooth',block:'nearest',inline:'start'})};document.querySelectorAll('#certificates .certificate-nav-btn').forEach(btn=>{btn.addEventListener('click',()=>{const direction=btn.dataset.direction==='next'?1:-1;goToCertificateItem(certificateIndex+direction)})});certificateItems.forEach((item,index)=>{item.addEventListener('click',()=>{const img=item.querySelector('img');if(!img||!certificateModal||!certificateModalImage)return;certificateModalImage.src=img.src;certificateModalImage.alt=img.alt||'Podgląd certyfikatu';certificateModal.hidden=false;certificateModal.setAttribute('aria-hidden','false');certificateIndex=index})});certificateModal?.querySelectorAll('[data-close="true"]').forEach(btn=>{btn.addEventListener('click',()=>{if(!certificateModal)return;certificateModal.hidden=true;certificateModal.setAttribute('aria-hidden','true')})})}
